mapper.sql:
c.tenant_id=#{query.tenantId} AND c.deleted=b'0'
AND c.customer_id=#{query.customerId}
AND c.name LIKE CONCAT('%',#{query.name},'%')
AND c.status=#{query.status}
AND c.primary_flag=#{query.primaryFlag}
AND EXISTS (SELECT 1 FROM cus_customer_master m WHERE m.id=c.customer_id AND m.tenant_id=c.tenant_id AND m.deleted=b'0'

    AND (
      (1=1

            AND m.department_code IN #{value}


            AND m.market_code IN #{value}


            AND m.system_code IN #{value}


            AND m.expend_code IN #{value}


            AND m.industry_code IN #{value}

      )
    )

)

mapper.select:
SELECT c.*, (SELECT m.name FROM cus_customer_master m WHERE m.id=c.customer_id AND m.tenant_id=c.tenant_id AND m.deleted=b'0') AS customer_name
FROM cus_customer_contact c WHERE 
ORDER BY c.id DESC LIMIT #{query.limit} OFFSET #{query.offset}
